export const FRESH_READS:NewsArticle[]=drafts.map(a=>({slug:a.slug,kind:a.kind,dateline:a.dateline,section:a.section,title:a.title,dek:a.dek,grades:"Grades 4–8",publishedOn:"2026-10-22",sources:a.src.map(url=>({name:new URL(url).hostname,url})),body:a.body.split(/\n\n/).map(t=>t.startsWith("## ")?{kind:"h" as const,text:t.slice(3)}:{kind:"p" as const,text:t}),words:a.words.map(([word,meaning])=>({word,meaning})),questions:a.qa.map(([question,answer,...wrong],i)=>{const k=[0,2,1,3,0][i];const options=[...wrong];options.splice(k,0,answer);return{question,options:options as NewsQuestion["options"],correct:letters[k]};})}));